//! Named time zones (`Europe/Stockholm`) from the IANA time zone database, compiled in
//! as tables ([`crate::tzdata`], generated by `tzdata/generate.py`): per zone, its UTC
//! offset changes, and a POSIX TZ rule for the years after the last one.

use crate::temporal::{civil_from_days, days_from_civil};
use crate::tzdata::{NAMES, VERSION, ZONES};

/// A named time zone: an index into the table's zone names.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Tz(u16);

/// A zone's data (shared by zones that are links of one another).
pub(crate) struct Zone {
    /// The offset (seconds east of UTC) before the first change.
    pub initial: i32,
    /// The rule for the years after the last change.
    pub rule: Option<Rule>,
    /// The UTC second of each change, ascending, and the offset from then on.
    pub changes: &'static [(i64, i32)],
}

/// A POSIX TZ rule (`CET-1CEST,M3.5.0,M10.5.0/3`): a standard offset, and maybe daylight
/// saving time with the dates it starts and ends each year.
pub(crate) struct Rule {
    pub std: i32,
    pub dst: Option<Dst>,
}

/// Daylight saving time in a [`Rule`]: its offset, and when it starts (in standard time)
/// and ends (in daylight time), as a date and the seconds after that day's midnight.
pub(crate) struct Dst {
    pub offset: i32,
    pub start: RuleDate,
    pub start_time: i64,
    pub end: RuleDate,
    pub end_time: i64,
}

/// A day of the year in a [`Rule`].
#[derive(Clone, Copy)]
// No zone uses the `Jn` and `n` forms today, but POSIX allows them and the generator
// writes them.
#[allow(dead_code)]
pub(crate) enum RuleDate {
    /// `Jn`: day 1..=365, February 29 never counted.
    Julian(i64),
    /// `n`: day 0..=365, counting February 29.
    Zero(i64),
    /// `Mm.w.d`: weekday `d` (0 = Sunday) of week `w` (5 = the last) of month `m`.
    Month(i64, i64, i64),
}

impl Tz {
    /// The zone named `name` (exactly, else ignoring case).
    pub fn find(name: &str) -> Option<Tz> {
        let i = match NAMES.binary_search_by(|(n, _)| n.cmp(&name)) {
            Ok(i) => i,
            Err(_) => NAMES
                .iter()
                .position(|(n, _)| n.eq_ignore_ascii_case(name))?,
        };
        Some(Tz(i as u16))
    }

    /// The zone's name, as the database spells it.
    pub fn name(self) -> &'static str {
        NAMES[self.0 as usize].0
    }

    /// The release of the time zone database (`2026f`).
    pub fn database_version() -> &'static str {
        VERSION
    }

    fn zone(self) -> &'static Zone {
        &ZONES[NAMES[self.0 as usize].1 as usize]
    }

    /// The UTC offset (seconds east) at the instant `utc` (seconds since the epoch).
    pub fn offset_at(self, utc: i64) -> i32 {
        let z = self.zone();
        match z.changes.partition_point(|&(t, _)| t <= utc) {
            0 => z.initial,
            n if n == z.changes.len() => match &z.rule {
                Some(rule) => rule.offset_at(utc),
                None => z.changes[n - 1].1,
            },
            n => z.changes[n - 1].1,
        }
    }

    /// The offset of the local time `local` (seconds since the epoch, in wall-clock
    /// time), and `local` moved past a gap if it falls in one (as Java does: by the
    /// gap's length). In an overlap, `prefer` wins if it is one of the two offsets,
    /// else the earlier one (the offset before the change).
    pub fn resolve(self, local: i64, prefer: Option<i32>) -> (i64, i32) {
        // At most one change within a day either side, in practice.
        let before = self.offset_at(local - 86_400);
        let after = self.offset_at(local + 86_400);
        let fits = |o: i32| self.offset_at(local - o as i64) == o;
        match (fits(before), fits(after)) {
            // A gap: before → after moves the clocks forward.
            (false, false) => (local + (after - before) as i64, after),
            (true, false) => (local, before),
            (false, true) => (local, after),
            // An overlap (or no change at all).
            (true, true) => match prefer {
                Some(p) if p == after => (local, after),
                _ => (local, before),
            },
        }
    }
}

impl Rule {
    fn offset_at(&self, utc: i64) -> i32 {
        let Some(dst) = &self.dst else {
            return self.std;
        };
        let year = civil_from_days((utc + self.std as i64).div_euclid(86_400)).0;
        // The year's switches, in UTC.
        let starts = day_of(year, dst.start) * 86_400 + dst.start_time - self.std as i64;
        let ends = day_of(year, dst.end) * 86_400 + dst.end_time - dst.offset as i64;
        let in_dst = if starts < ends {
            starts <= utc && utc < ends
        } else {
            !(ends <= utc && utc < starts)
        };
        if in_dst { dst.offset } else { self.std }
    }
}

/// Days since the epoch of `d` in `year`.
fn day_of(year: i64, d: RuleDate) -> i64 {
    let jan1 = days_from_civil(year, 1, 1);
    let leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
    match d {
        RuleDate::Julian(n) => jan1 + n - 1 + i64::from(leap && n >= 60),
        RuleDate::Zero(n) => jan1 + n,
        RuleDate::Month(m, w, wd) => {
            let first = days_from_civil(year, m as u32, 1);
            // 1970-01-01 was a Thursday (4).
            let first_wd = (first + 4).rem_euclid(7);
            let mut day = first + (wd - first_wd).rem_euclid(7) + (w - 1) * 7;
            let next = if m == 12 {
                days_from_civil(year + 1, 1, 1)
            } else {
                days_from_civil(year, m as u32 + 1, 1)
            };
            while day >= next {
                day -= 7;
            }
            day
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn utc(y: i64, m: u32, d: u32, h: i64) -> i64 {
        days_from_civil(y, m, d) * 86_400 + h * 3600
    }

    #[test]
    fn offsets() {
        let sto = Tz::find("Europe/Stockholm").unwrap();
        assert_eq!(sto.name(), "Europe/Stockholm");
        assert_eq!(Tz::find("europe/stockholm"), Some(sto));
        assert!(Tz::find("Frost/Nixon").is_none());
        assert_eq!(sto.offset_at(utc(1984, 10, 11, 12)), 3600);
        assert_eq!(sto.offset_at(utc(1984, 7, 20, 12)), 7200);
        assert_eq!(sto.offset_at(utc(1818, 7, 21, 12)), 3208); // local mean time, +00:53:28
        // Past the table, from the rule: last Sunday of March at 01:00 UTC.
        assert_eq!(sto.offset_at(utc(2100, 3, 28, 0)), 3600);
        assert_eq!(sto.offset_at(utc(2100, 3, 28, 1)), 7200);
        assert_eq!(sto.offset_at(utc(2100, 10, 31, 0)), 7200);
        assert_eq!(sto.offset_at(utc(2100, 10, 31, 1)), 3600);
        assert_eq!(
            Tz::find("Australia/Eucla")
                .unwrap()
                .offset_at(utc(2015, 7, 21, 0)),
            8 * 3600 + 45 * 60
        );
        assert_eq!(
            Tz::find("Pacific/Honolulu")
                .unwrap()
                .offset_at(utc(1984, 10, 28, 0)),
            -10 * 3600
        );
        // Southern hemisphere: daylight time spans the new year.
        let syd = Tz::find("Australia/Sydney").unwrap();
        assert_eq!(syd.offset_at(utc(2090, 1, 15, 0)), 11 * 3600);
        assert_eq!(syd.offset_at(utc(2090, 7, 15, 0)), 10 * 3600);
    }

    #[test]
    fn rule_dates() {
        let d = |y, m, dd| days_from_civil(y, m, dd);
        assert_eq!(day_of(2024, RuleDate::Julian(60)), d(2024, 3, 1)); // February 29 skipped
        assert_eq!(day_of(2024, RuleDate::Zero(59)), d(2024, 2, 29));
        assert_eq!(day_of(2026, RuleDate::Month(3, 5, 0)), d(2026, 3, 29)); // last Sunday of March
        assert_eq!(day_of(2026, RuleDate::Month(11, 1, 0)), d(2026, 11, 1));
    }

    #[test]
    fn local_times() {
        let sto = Tz::find("Europe/Stockholm").unwrap();
        let local = |y, m, d, h| utc(y, m, d, h);
        // A gap: 2017-03-26 02:30 does not exist, it becomes 03:30 +02:00.
        assert_eq!(
            sto.resolve(local(2017, 3, 26, 2) + 1800, None),
            (local(2017, 3, 26, 3) + 1800, 7200)
        );
        // An overlap: 2017-10-29 02:30 happens twice; the earlier offset wins unless preferred.
        assert_eq!(sto.resolve(local(2017, 10, 29, 2) + 1800, None).1, 7200);
        assert_eq!(
            sto.resolve(local(2017, 10, 29, 2) + 1800, Some(3600)).1,
            3600
        );
        assert_eq!(sto.resolve(local(2017, 10, 29, 12), Some(7200)).1, 3600);
    }
}
